package com.pocketmusic.android;
import android.content.*;
import android.app.job.*;
import android.os.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Predicate;
import org.json.*;
import com.yausername.youtubedl_android.*;

/** App-owned rotating offline music. The ownership ledger is the only authority for deletion. */
final class SmartDownloads {
 static final int DAILY=7201,NOW=7202;static final long MIB=1024L*1024,MAX_FILE=20*MIB;
 static final class Run {volatile boolean stopped,retry;volatile String process="";}
 interface Fetcher {File fetch(Context c,Track track,File stage,Run run)throws Exception;}
 static Fetcher fetcher=SmartDownloads::download;static Recommendations.SongSource catalogue=MusicCatalog::songs;
 static Predicate<Context> eligible=SmartDownloads::deviceEligible;
 private static final AtomicBoolean running=new AtomicBoolean();
 static boolean busy(){return running.get();}
 static boolean enabled(Context c){return c.getSharedPreferences("music",0).getBoolean("smartEnabled",false);}
 static int countLimit(Context c){int n=c.getSharedPreferences("music",0).getInt("smartCount",25);return n==10||n==50?n:25;}
 static long byteLimit(Context c){int n=c.getSharedPreferences("music",0).getInt("smartMb",250);return (n==100||n==500?n:250)*MIB;}
 static void status(Context c,String text,int progress){c.getSharedPreferences("music",0).edit().putString("smartStatus",text).putInt("smartProgress",progress).apply();}
 static String status(Context c){return c.getSharedPreferences("music",0).getString("smartStatus",enabled(c)?"Waiting for an eligible update":"Off");}
 static void schedule(Context c,boolean now){JobScheduler scheduler=c.getSystemService(JobScheduler.class);if(!enabled(c)){scheduler.cancel(DAILY);scheduler.cancel(NOW);return;}JobInfo.Builder b=new JobInfo.Builder(now?NOW:DAILY,new ComponentName(c,SmartDownloadJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_UNMETERED).setRequiresCharging(c.getSharedPreferences("music",0).getBoolean("smartCharging",false)).setRequiresBatteryNotLow(true).setRequiresStorageNotLow(true).setBackoffCriteria(900000,JobInfo.BACKOFF_POLICY_EXPONENTIAL);if(now)b.setMinimumLatency(1000);else b.setPeriodic(86400000L,14400000L).setPersisted(true);if(now||scheduler.getPendingJob(DAILY)==null){int result=scheduler.schedule(b.build());if(result!=JobScheduler.RESULT_SUCCESS)status(c,"Android could not schedule the update. Open Smart downloads to retry.",0);}}
 static void configure(Context c,boolean enabled,int songs,int mb,boolean charging){c.getSharedPreferences("music",0).edit().putBoolean("smartEnabled",enabled).putInt("smartCount",songs).putInt("smartMb",mb).putBoolean("smartCharging",charging).apply();JobScheduler s=c.getSystemService(JobScheduler.class);s.cancel(DAILY);s.cancel(NOW);status(c,enabled?"Waiting for unmetered network and battery conditions":"Off · existing smart copies are kept",0);schedule(c,false);if(enabled)schedule(c,true);}
 static synchronized void requestIfDue(Context c){if(!enabled(c)||busy())return;android.content.SharedPreferences prefs=c.getSharedPreferences("music",0);long now=System.currentTimeMillis();if(now-prefs.getLong("smartLastRequest",0)<900000L)return;prefs.edit().putLong("smartLastRequest",now).apply();JobScheduler scheduler=c.getSystemService(JobScheduler.class);if(scheduler.getPendingJob(NOW)==null)schedule(c,true);}
 static boolean deviceEligible(Context c){if(!LocalPlayerService.unmeteredPreparation(c)||DownloadService.busy)return false;LocalPlayerService player=LocalPlayerService.active;if(player!=null&&(player.state.equals("playing")||player.state.equals("buffering")||player.state.equals("preparing")))return false;Intent battery=c.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(battery==null)return false;int level=battery.getIntExtra(BatteryManager.EXTRA_LEVEL,0),scale=battery.getIntExtra(BatteryManager.EXTRA_SCALE,100),state=battery.getIntExtra(BatteryManager.EXTRA_STATUS,0);boolean charging=state==BatteryManager.BATTERY_STATUS_CHARGING||state==BatteryManager.BATTERY_STATUS_FULL;if(scale<=0||100L*level/scale<20||c.getSharedPreferences("music",0).getBoolean("smartCharging",false)&&!charging)return false;return MusicRepository.folder(c).getUsableSpace()>=500*MIB+MAX_FILE&&c.getCacheDir().getUsableSpace()>=100*MIB+MAX_FILE;}
 private static JSONObject index(Context c){try{return new JSONObject(c.getSharedPreferences("music",0).getString("smartFiles","{}"));}catch(Exception e){return new JSONObject();}}
 private static void save(Context c,JSONObject index){c.getSharedPreferences("music",0).edit().putString("smartFiles",index.toString()).commit();}
 static synchronized List<File> files(Context c){List<File> files=new ArrayList<>();JSONObject ledger=index(c);Iterator<String> keys=ledger.keys();while(keys.hasNext()){String name=keys.next();File f=new File(MusicRepository.folder(c),name);JSONObject record=ledger.optJSONObject(name);if(matches(c,f,record))files.add(f);}files.sort(Comparator.comparingLong(File::lastModified));return files;}
 private static boolean matches(Context c,File f,JSONObject record){try{return record!=null&&f.isFile()&&f.getCanonicalFile().getParentFile().equals(MusicRepository.folder(c).getCanonicalFile())&&f.getName().startsWith("Smart - ")&&f.length()==record.getLong("bytes")&&f.lastModified()==record.getLong("modified");}catch(Exception e){return false;}}
 static synchronized boolean owned(Context c,File f){return matches(c,f,index(c).optJSONObject(f.getName()));}
 private static List<String> names(JSONObject ledger){List<String> names=new ArrayList<>();Iterator<String> keys=ledger.keys();while(keys.hasNext())names.add(keys.next());return names;}
 static synchronized void keep(Context c,String id){JSONObject ledger=index(c);for(String name:names(ledger))if(ledger.optJSONObject(name)!=null&&id.equals(ledger.optJSONObject(name).optString("id")))ledger.remove(name);save(c,ledger);}
 static synchronized void removed(Context c,File f,boolean exclude){JSONObject ledger=index(c);JSONObject record=ledger.optJSONObject(f.getName());if(record==null)return;ledger.remove(f.getName());save(c,ledger);if(exclude){Set<String> ids=excluded(c);ids.add(record.optString("id"));c.getSharedPreferences("music",0).edit().putStringSet("smartExcluded",ids).apply();}}
 static Set<String> excluded(Context c){return new HashSet<>(c.getSharedPreferences("music",0).getStringSet("smartExcluded",Set.of()));}
 static long bytes(Context c){long sum=0;for(File f:files(c))sum+=f.length();return sum;}
 private static boolean inUse(Context c,File f){LocalPlayerService p=LocalPlayerService.active;if(p!=null&&(p.path.equals(f.getAbsolutePath())||TrackFiles.videoId(f)!=null&&p.queuedAudioIds.contains(TrackFiles.videoId(f))))return true;for(DownloadQueue.Job j:DownloadService.jobs(c))if(j.pending()&&j.id.equals(TrackFiles.videoId(f)))return true;return false;}
 private static boolean drop(Context c,File f)throws Exception{boolean deleted=false;synchronized(SmartDownloads.class){if(owned(c,f)&&!inUse(c,f)&&f.delete()){removed(c,f,false);deleted=true;}}if(deleted)LocalDownloads.forget(c,f);return deleted;}
 static void clear(Context c)throws Exception{if(running.get())throw new IOException("Pause Smart downloads and wait for the current update to stop.");for(File f:files(c))drop(c,f);status(c,enabled(c)?"Smart copies cleared · future updates remain enabled":"Smart copies cleared",0);}
 static void refresh(Context c,Run run){if(!running.compareAndSet(false,true)){run.retry=true;return;}File stage=null;long started=SystemClock.elapsedRealtime();try{
  if(!enabled(c))return;if(!eligible.test(c)){run.retry=true;status(c,"Waiting for unmetered network, charging/battery, idle playback and free space",0);return;}if(System.currentTimeMillis()<c.getSharedPreferences("music",0).getLong("youtubeCooldown",0)){run.retry=true;status(c,"YouTube is limiting requests. Update will wait.",0);return;}
  YouTubeSession.cleanAbandoned(c);File[] oldStages=c.getCacheDir().listFiles();if(oldStages!=null)for(File old:oldStages)if(old.getName().matches("smart-stage-[a-f0-9-]{36}"))cleanStage(c,old);String scope=Recommendations.scope(c);List<Track> recent=MusicTaste.recent(c),likes=MusicTaste.liked(c),discovery=Recommendations.cached(c);if(!Recommendations.account(c)&&recent.isEmpty()&&likes.isEmpty()&&MusicTaste.artists(c).isEmpty()&&discovery.isEmpty()){status(c,"Connect YouTube Music or like songs to build your offline collection",0);return;}if(!Recommendations.fresh(c))try{run.process="smart-feed-"+UUID.randomUUID();Recommendations.fetch(c,run.process,catalogue);discovery=Recommendations.cached(c);}catch(Exception error){if(discovery.isEmpty()&&recent.isEmpty()&&likes.isEmpty()){run.retry=true;throw error;}}
  if(recent.isEmpty()&&likes.isEmpty()&&discovery.isEmpty()){status(c,Recommendations.account(c)?"Account music is not ready · open Home to reconnect or refresh":"Connect YouTube Music or like songs to build your offline collection",0);run.retry=Recommendations.account(c);return;}
  Set<String> manual=new HashSet<>();for(File f:MusicRepository.files(c))if(TrackFiles.audio(f)&&!owned(c,f))manual.add(TrackFiles.videoId(f));Set<String> excluded=excluded(c);excluded.addAll(MusicTaste.hidden(c));List<Track> target=SmartDownloadPolicy.select(recent,likes,discovery,excluded,manual,countLimit(c));if(target.isEmpty()){status(c,"No new eligible music · existing smart copies are kept",0);return;}Set<String> wanted=new HashSet<>();for(Track t:target)wanted.add(t.id);
  check(c,run,scope);for(File f:files(c)){check(c,run,scope);if(!wanted.contains(TrackFiles.videoId(f)))drop(c,f);}for(File f:files(c)){check(c,run,scope);if(files(c).size()<=countLimit(c)&&bytes(c)<=byteLimit(c))break;drop(c,f);}int completed=0,attempts=0,failures=0;String lastFailure="";stage=new File(c.getCacheDir(),"smart-stage-"+UUID.randomUUID());if(!stage.mkdir())throw new IOException("Could not prepare storage.");
  for(Track t:target){check(c,run,scope);if(attempts>=5||SystemClock.elapsedRealtime()-started>240000)break;if(MusicRepository.local(c,t.id)!=null)continue;if(files(c).size()>=countLimit(c)||bytes(c)+MAX_FILE>byteLimit(c))break;attempts++;if(!stage.isDirectory()&&!stage.mkdir())throw new IOException("Could not prepare storage.");try{run.process="smart-download-"+UUID.randomUUID();status(c,"Preparing "+t.title,0);File audio=fetcher.fetch(c,t,stage,run);check(c,run,scope);if(!audio.getCanonicalFile().getParentFile().equals(stage.getCanonicalFile())||!audio.isFile()||audio.length()==0||audio.length()>MAX_FILE||audio.length()+bytes(c)>byteLimit(c))throw new IOException("Smart download exceeded its storage limit.");
   File temporary=File.createTempFile(".smart-",".part",MusicRepository.folder(c));try{try(InputStream input=new FileInputStream(audio);OutputStream output=new FileOutputStream(temporary)){byte[] buffer=new byte[32768];int n;while((n=input.read(buffer))!=-1)output.write(buffer,0,n);}
   synchronized(SmartDownloads.class){check(c,run,scope);if(MusicRepository.local(c,t.id)!=null||excluded(c).contains(t.id)||MusicTaste.hidden(c).contains(t.id))continue;String clean=t.title.replaceAll("[^\\p{L}\\p{N} ._()-]","_");if(clean.length()>70)clean=clean.substring(0,70);File destination=new File(MusicRepository.folder(c),"Smart - "+clean+" ["+t.id+"].m4a");if(destination.exists()||!temporary.renameTo(destination))throw new IOException("Could not finish smart download.");JSONObject ledger=index(c);ledger.put(destination.getName(),new JSONObject().put("id",t.id).put("bytes",destination.length()).put("modified",destination.lastModified()));save(c,ledger);MusicTaste.remember(c,List.of(t));}}finally{temporary.delete();}completed++;}catch(Exception failure){if(run.stopped||Thread.currentThread().isInterrupted()||failure instanceof InterruptedIOException||!enabled(c)||!eligible.test(c)||!scope.equals(Recommendations.scope(c)))throw new InterruptedIOException("Update paused");if(DownloadErrors.rateLimited(failure.getMessage())||DownloadErrors.needsLogin(failure.getMessage()))throw failure;failures++;lastFailure=DownloadErrors.friendly(failure.getMessage());}finally{cleanStage(c,stage);}
  }boolean remaining=false;for(Track t:target)if(MusicRepository.local(c,t.id)==null){remaining=true;break;}run.retry=remaining&&files(c).size()<countLimit(c)&&bytes(c)+MAX_FILE<=byteLimit(c);c.getSharedPreferences("music",0).edit().putLong("smartLastUpdate",System.currentTimeMillis()).apply();status(c,files(c).size()+" smart songs ready · "+completed+" added"+(failures>0?" · "+failures+" skipped · "+lastFailure:(run.retry?" · more queued automatically":"")),100);
 }catch(InterruptedIOException e){run.retry=enabled(c);status(c,"Update paused · eligible conditions or account changed",0);}catch(Exception e){run.retry=enabled(c);if(DownloadErrors.rateLimited(e.getMessage()))c.getSharedPreferences("music",0).edit().putLong("youtubeCooldown",System.currentTimeMillis()+60000).apply();status(c,"Update stopped · "+DownloadErrors.friendly(e.getMessage()),0);}finally{if(stage!=null)cleanStage(c,stage);if(!enabled(c))status(c,"Off · existing smart copies are kept",0);running.set(false);}}
 private static void cleanStage(Context c,File directory){try{File base=c.getCacheDir().getCanonicalFile(),dir=directory.getCanonicalFile();if(!dir.getParentFile().equals(base)||!dir.getName().matches("smart-stage-[a-f0-9-]{36}"))return;File[] files=dir.listFiles();if(files!=null)for(File file:files)if(file.isFile()&&file.getCanonicalFile().getParentFile().equals(dir))file.delete();dir.delete();}catch(IOException ignored){}}
 private static void check(Context c,Run run,String scope)throws InterruptedIOException{if(run.stopped||Thread.currentThread().isInterrupted()||!enabled(c)||!eligible.test(c)||!scope.equals(Recommendations.scope(c)))throw new InterruptedIOException("Smart update paused");}
 private static File download(Context c,Track track,File stage,Run run)throws Exception{if(run.stopped||Thread.currentThread().isInterrupted())throw new InterruptedIOException("Cancelled");String sessionScope=Recommendations.scope(c);MusicRepository.init(c);File cookies=null;try{cookies=YouTubeSession.lease(c);YoutubeDLRequest request=new YoutubeDLRequest(VideoLinks.url(track.id));request.addOption("--no-playlist").addOption("--no-overwrites").addOption("--socket-timeout","15").addOption("--retries","0").addOption("--extractor-retries","0").addOption("--remote-components","ejs:github").addOption("--sleep-requests","1").addOption("--max-filesize","20M").addOption("--match-filter","duration >= 30 & duration <= 600").addOption("--concurrent-fragments","1").addOption("-f","bestaudio[ext=m4a]").addOption("-o",new File(stage,track.id+".%(ext)s").getAbsolutePath());if(cookies!=null)request.addOption("--cookies",cookies.getAbsolutePath());long[] tick={0};if(run.stopped||Thread.currentThread().isInterrupted())throw new InterruptedIOException("Cancelled");YoutubeDL.getInstance().execute(request,run.process,false,(p,eta,line)->{if(run.stopped||Thread.currentThread().isInterrupted()){cancelProcess(run.process);throw new java.util.concurrent.CancellationException();}if(SystemClock.elapsedRealtime()-tick[0]>1000){tick[0]=SystemClock.elapsedRealtime();status(c,"Downloading "+track.title,Math.max(0,Math.min(99,Math.round(p))));if(!eligible.test(c)||!enabled(c)||!sessionScope.equals(Recommendations.scope(c))){run.retry=true;cancelProcess(run.process);throw new java.util.concurrent.CancellationException();}}return kotlin.Unit.INSTANCE;});return new File(stage,track.id+".m4a");}finally{if(cookies!=null)cookies.delete();}}
 static void cancelProcess(String process){try{if(!process.isEmpty()){MusicCatalog.cancel(process);AccountMusic.cancel(process);YoutubeDL.getInstance().destroyProcessById(process);}}catch(Exception ignored){}}
}
